public final class BinarySearch {
    private static final int NOT_FOUND = -1;

    private BinarySearch() {
    }

    public static SearchResult search(int[] sortedValues, int target) {
        return SearchResult.fromIndex(binarySearch(sortedValues, target));
    }

    public static int binarySearch(int[] sortedValues, int target) {
        java.util.Objects.requireNonNull(sortedValues, "sortedValues");

        int left = 0;
        int right = sortedValues.length - 1;

        while (left <= right) {
            int middle = middleIndex(left, right);
            int candidate = sortedValues[middle];

            if (candidate == target) {
                return middle;
            }

            if (candidate < target) {
                left = middle + 1;
            } else {
                right = middle - 1;
            }
        }

        return NOT_FOUND;
    }

    private static int middleIndex(int left, int right) {
        return left + (right - left) / 2;
    }

    public static void main(String[] args) {
        BinarySearchDemo.run();
    }
}

public final class SearchResult {
    private static final SearchResult NOT_FOUND = new SearchResult(-1);

    private final int index;

    private SearchResult(int index) {
        this.index = index;
    }

    public static SearchResult fromIndex(int index) {
        if (index < 0) {
            return notFound();
        }

        return foundAt(index);
    }

    public static SearchResult foundAt(int index) {
        if (index < 0) {
            throw new IllegalArgumentException("Result index must be non-negative.");
        }

        return new SearchResult(index);
    }

    public static SearchResult notFound() {
        return NOT_FOUND;
    }

    public boolean isFound() {
        return index >= 0;
    }

    public int index() {
        if (!isFound()) {
            throw new IllegalStateException("Search result has no index.");
        }

        return index;
    }
}

final class BinarySearchTest {
    private BinarySearchTest() {
    }

    public static void main(String[] args) {
        assertIndex(3, new int[] { 2, 3, 4, 10, 40 }, 10);
        assertIndex(-1, new int[] { 2, 3, 4, 10, 40 }, 5);
        assertIndex(0, new int[] { 7 }, 7);
        assertIndex(-1, new int[] {}, 7);
        assertThrowsNullPointer(new ThrowingRunnable() {
            public void run() {
                BinarySearch.binarySearch(null, 7);
            }
        });

        assertSearchResultFound(3, new int[] { 2, 3, 4, 10, 40 }, 10);
        assertSearchResultNotFound(new int[] { 2, 3, 4, 10, 40 }, 5);

        assertEquals(
                "Element is present at index 3",
                SearchResultFormatter.format(SearchResult.foundAt(3)));
        assertEquals(
                "Element is not present in array",
                SearchResultFormatter.format(SearchResult.notFound()));

        System.out.println("All tests passed");
    }

    private static void assertIndex(int expected, int[] sortedValues, int target) {
        assertEquals(expected, BinarySearch.binarySearch(sortedValues, target));
    }

    private static void assertSearchResultFound(int expectedIndex, int[] sortedValues, int target) {
        SearchResult result = BinarySearch.search(sortedValues, target);

        if (!result.isFound()) {
            throw new AssertionError("Expected search result to be found.");
        }

        assertEquals(expectedIndex, result.index());
    }

    private static void assertSearchResultNotFound(int[] sortedValues, int target) {
        SearchResult result = BinarySearch.search(sortedValues, target);

        if (result.isFound()) {
            throw new AssertionError("Expected search result to be not found.");
        }
    }

    private static void assertEquals(int expected, int actual) {
        if (expected != actual) {
            throw new AssertionError("Expected " + expected + " but got " + actual + ".");
        }
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but got \"" + actual + "\".");
        }
    }

    private static void assertThrowsNullPointer(ThrowingRunnable runnable) {
        try {
            runnable.run();
            throw new AssertionError("Expected NullPointerException.");
        } catch (NullPointerException expected) {
            assertEquals("sortedValues", expected.getMessage());
        }
    }

    private interface ThrowingRunnable {
        void run();
    }
}

